/* Guided prototype: locate → confirm dimensions → compare products. */
function simplePoint(){const r=state.lookupResult;if(r?.status==='point'||r?.status==='candidate'&&r.method!=='registration')return {lat:r.lat,lng:r.lng,method:r.method};if(state.lotConfirmed)return {lat:state.lot.lat,lng:state.lot.lng,method:state.lookupContext?.location_method||state.lookupContext?.method};return null}
function simpleLocationStatus(){const r=state.lookupResult,p=simplePoint();if(r?.status==='error'||r?.status==='unresolved')return lookupResult();if(!p&&r?.status!=='candidate')return '';return `<section id="lookup-result" class="simple-point" tabindex="-1" aria-label="Localização selecionada"><span class="simple-point-icon">${icon('check')}</span><div><strong>${r?.status==='candidate'?'Exemplo encontrado':state.lotConfirmed&&!state.lot.manualMeasures?esc(state.lot.name):'Localização marcada'}</strong><p>${p?`${number(p.lat,6)}, ${number(p.lng,6)}`:'Matrícula do conjunto demonstrativo'} · João Pessoa / PB</p></div><button class="btn" data-action="open-location-picker" aria-label="Alterar localização no mapa">Alterar</button></section>`}
function simpleMeasures(){const point=simplePoint(),r=state.lookupResult,l=state.lot;if(r?.status==='candidate'){const candidate=lots.find(x=>x.id===r.lotId);return `<section class="simple-measures panel"><div class="simple-section-title"><span>2</span><h2>Confirme as medidas</h2></div><div class="simple-known"><span class="eyebrow">EXEMPLO DEMONSTRATIVO</span><h3>${esc(candidate.name)}</h3><div><strong>${number(candidate.area)} <small>m²</small></strong><p>Frente de ${number(candidate.width)} m · profundidade de ${number(candidate.depth)} m</p></div><p>Estas medidas pertencem a um lote fictício. Não foram obtidas de cartório ou cadastro oficial.</p></div>${btn('Ver possibilidades deste exemplo','arrowRight','quick-candidate','primary wide')}</section>`}if(state.lotConfirmed&&!l.manualMeasures&&!state.lookupDirty)return `<section class="simple-measures panel"><div class="simple-section-title"><span>2</span><h2>Seu terreno está pronto para simular</h2></div><div class="simple-known"><span class="eyebrow">${l.custom?'GEOMETRIA INFORMADA · ESTIMADA':'LOTE DE DEMONSTRAÇÃO'}</span><h3>${esc(l.name)}</h3><div><strong>${number(l.area)} <small>m²</small></strong><p>Frente de ${number(l.width)} m · profundidade de ${number(l.depth)} m</p></div></div>${btn('Ver possibilidades de construção','arrowRight','analyze','primary wide')}<p class="simple-small-note">As regras urbanísticas continuam demonstrativas.</p></section>`;
 if(!point||state.lookupDirty)return `<section class="simple-measures panel waiting-measures"><div class="simple-section-title"><span>2</span><h2>Confirme as medidas</h2></div><div class="simple-waiting-icon">${icon('ruler')}</div><h3>Primeiro, localize o terreno.</h3><p>Depois, informe a área e a medida da frente. Com isso, você já poderá explorar as possibilidades.</p><p class="simple-small-note">Se tiver o perímetro em GeoJSON, também pode importá-lo nas opções avançadas.</p></section>`;
 const values=state.quickMeasureValues;return `<section class="simple-measures panel"><div class="simple-section-title"><span>2</span><h2>Quais são as medidas do terreno?</h2></div><p class="simple-section-description">Informe duas medidas para uma primeira simulação.</p><form id="quick-measures" novalidate><div class="quick-measure-grid"><div><label for="quick-area">Área do terreno <span>(m²)</span></label><input id="quick-area" name="area" inputmode="decimal" autocomplete="off" placeholder="Ex.: 1.200" value="${esc(values.area)}" data-quick-measure="area" aria-describedby="quick-area-help quick-measure-error"><small id="quick-area-help">Área total aproximada do lote.</small></div><div><label for="quick-frontage">Frente do terreno <span>(m)</span></label><input id="quick-frontage" name="frontage" inputmode="decimal" autocomplete="off" placeholder="Ex.: 30" value="${esc(values.frontage)}" data-quick-measure="frontage" aria-describedby="quick-frontage-help quick-measure-error"><small id="quick-frontage-help">Largura da frente voltada para a rua.</small></div></div><p id="quick-measure-error" class="quick-error" role="alert" hidden></p><div class="simple-assumption">${icon('info')}<p>Para esta simulação, vamos assumir um terreno retangular e plano. A profundidade será estimada pela área dividida pela frente.</p></div><button type="submit" class="btn primary wide">${icon('arrowRight')}Ver possibilidades de construção</button><p class="simple-small-note">Estimativa exploratória. O perímetro, o zoneamento e as regras precisam ser validados para um estudo técnico.</p></form></section>`}
function simpleFindView(){const point=simplePoint();return `<div class="simple-start"><section class="simple-locate panel"><div class="simple-section-title"><span>1</span><h2>Onde fica o terreno?</h2></div><p class="simple-section-description">Veja casas e terrenos na vista aérea e marque a localização.</p><button class="simple-map-launch" data-action="open-location-picker"><span class="simple-map-art" aria-hidden="true"><i></i><b>${icon('pin')}</b></span><strong>${point?'Ajustar localização no mapa':'Marcar terreno no mapa'}</strong><span>Aérea, ruas e relevo 3D · toque para explorar ${icon('arrowRight')}</span></button>${simpleLocationStatus()}<details class="simple-lookup-details" id="other-location-methods" ${state.simpleLookupOpen?'open':''}><summary>Prefiro informar coordenadas, matrícula ou endereço</summary>${lookupFields(false)}</details></section>${simpleMeasures()}</div><details class="simple-geometry" id="simple-geometry" ${state.drawing||state.simpleGeometryOpen?'open':''}><summary>${icon('layers')}Já tenho o perímetro do terreno · opções avançadas</summary><div class="simple-geometry-actions">${btn('Importar GeoJSON','upload','import')}${btn('Desenhar perímetro ilustrativo','draw','draw')}</div><p>GeoJSON usa coordenadas geográficas. O desenho abaixo é esquemático, em escala fictícia.</p>${state.drawing?mapPanel(false):''}</details><div class="simple-outcome"><span>${icon('building')}Casa, apartamentos, salas comerciais e flats</span><p>Compare área, pavimentos e unidades. Abra o 3D e o relatório quando quiser aprofundar.</p><small>Protótipo com regras e cenários demonstrativos.</small></div>`}
function parseMeasure(text){const raw=String(text).trim().replace(/\s/g,'');if(/^\d{1,3}(?:\.\d{3})+(?:,\d+)?$/.test(raw))return Number(raw.replace(/\./g,'').replace(',','.'));if(!/^\d+(?:[.,]\d+)?$/.test(raw))return null;return Number(raw.replace(',','.'))}
function submitQuickMeasures(){const area=parseMeasure($('#quick-area').value),frontage=parseMeasure($('#quick-frontage').value),point=simplePoint();const error=(text,id)=>{const el=$('#quick-measure-error');el.textContent=text;el.hidden=false;$$('#quick-measures input').forEach(e=>e.removeAttribute('aria-invalid'));$('#'+id).setAttribute('aria-invalid','true');$('#'+id).focus()};if(!point||state.lookupDirty)return error('Confirme a localização antes de simular.','quick-area');if(area===null||!Number.isFinite(area)||area<50||area>1e6)return error('Informe uma área entre 50 e 1.000.000 m². Exemplo: 1.200.','quick-area');if(frontage===null||!Number.isFinite(frontage)||frontage<3||frontage>1000)return error('Informe a frente entre 3 e 1.000 metros. Exemplo: 30.','quick-frontage');const depth=area/frontage;if(depth<3||depth>3000)return error('Confira as medidas: a profundidade estimada precisa ficar entre 3 e 3.000 metros.','quick-frontage');state.lot={id:state.lot.manualMeasures?state.lot.id:'M'+Date.now().toString(36).slice(-6).toUpperCase(),name:'Terreno informado',address:'Medidas informadas pelo usuário',area,width:frontage,depth,lat:point.lat,lng:point.lng,zone:'Não identificado',coastal:false,custom:true,manualMeasures:true,geometryVerified:false,position:[386,245]};state.lotConfirmed=true;state.lookupDirty=false;state.lookupResult=null;state.customPolygon=null;state.lookupContext={method:'measures',location_method:point.method||'coordinates',lat:point.lat,lng:point.lng,verified:false,geometry_assumption:'rectangle',input_area_m2:area,input_frontage_m:frontage};state.simpleLookupOpen=false;state.simpleGeometryOpen=false;state.page='analysis';state.step=2;state.analyzed=true;render();focusMain()}
function quickDemo(){selectLot(lots[0].id,{method:'example',verified:false});state.step=2;state.analyzed=true;render();focusMain()}
function quickCandidate(){const r=state.lookupResult;if(!r||r.status!=='candidate')return;confirmLookup();state.step=2;state.analyzed=true;render();focusMain()}
function resetSimpleStudy(){state.lotConfirmed=false;state.lookupResult=null;state.lookupContext=null;state.lookupDirty=false;state.mapPickedPoint=null;state.lookupValues={latitude:'',longitude:'',registration:'',office:'',address:''};state.quickMeasureValues={area:'',frontage:''};state.simpleLookupOpen=false;state.simpleGeometryOpen=false;state.customPolygon=null;state.drawing=false}
document.addEventListener('submit',e=>{if(e.target.id==='quick-measures'){e.preventDefault();submitQuickMeasures()}});
document.addEventListener('input',e=>{if(e.target.dataset.quickMeasure)state.quickMeasureValues[e.target.dataset.quickMeasure]=e.target.value});
document.addEventListener('toggle',e=>{if(e.target.id==='other-location-methods'){state.simpleLookupOpen=e.target.open;if(e.target.open&&state.lookupMode==='map'){state.lookupMode='coordinates';render();$('#other-location-methods summary').focus({preventScroll:true})}}if(e.target.id==='simple-geometry')state.simpleGeometryOpen=e.target.open},true);
